package test;
import org.eclipse.jface.dialogs.IDialogConstants;

public class MyDialog {
    // Use the standard OK button ID for a more conventional dialog experience
    private static final int GO_BUTTON_ID = IDialogConstants.OK_ID;

    public void setup() {
        int currentId = IDialogConstants.OK_ID;
        System.out.println(currentId);
    }
}

